const { api, action, params } = $input.first().json;

const apiConfigs = {
  google_ads: {
    base_url: 'https://googleads.googleapis.com/v17',
    endpoints: {
      campaigns: { method: 'GET', path: '/customers/{customer_id}/googleAds:searchStream', body: { query: `SELECT campaign.id, campaign.name, campaign.status, metrics.impressions, metrics.clicks, metrics.cost_micros FROM campaign WHERE segments.date DURING ${params.date_range || 'LAST_7_DAYS'}` } },
      ad_groups: { method: 'GET', path: '/customers/{customer_id}/googleAds:searchStream', body: { query: 'SELECT ad_group.id, ad_group.name, ad_group.status FROM ad_group' } },
      metrics: { method: 'GET', path: '/customers/{customer_id}/googleAds:searchStream', body: { query: 'SELECT metrics.impressions, metrics.clicks, metrics.cost_micros, metrics.conversions FROM customer' } }
    }
  },
  meta_ads: {
    base_url: 'https://graph.facebook.com/v19.0',
    endpoints: {
      campaigns: { method: 'GET', path: '/act_{ad_account_id}/campaigns', query: { fields: 'id,name,status,objective,daily_budget' } },
      ad_sets: { method: 'GET', path: '/act_{ad_account_id}/adsets', query: { fields: 'id,name,status,daily_budget,targeting' } },
      insights: { method: 'GET', path: '/act_{ad_account_id}/insights', query: { fields: 'impressions,clicks,spend,actions', date_preset: params.date_range || 'last_7d' } }
    }
  },
  linkedin_ads: {
    base_url: 'https://api.linkedin.com/v2',
    endpoints: {
      campaigns: { method: 'GET', path: '/adCampaignsV2', query: { q: 'search' } },
      analytics: { method: 'GET', path: '/adAnalyticsV2', query: { q: 'analytics', dateRange: params.date_range } }
    }
  },
  tiktok_ads: {
    base_url: 'https://business-api.tiktok.com/open_api/v1.3',
    endpoints: {
      campaigns: { method: 'GET', path: '/campaign/get/', query: { advertiser_id: params.advertiser_id } },
      reports: { method: 'GET', path: '/report/integrated/get/', query: { advertiser_id: params.advertiser_id, report_type: 'BASIC' } }
    }
  }
};

const config = apiConfigs[api];
if (!config) {
  return [{ json: { error: true, message: `Unknown marketing API: ${api}` } }];
}

const endpoint = config.endpoints[action];
if (!endpoint) {
  return [{ json: { error: true, message: `Unknown action '${action}' for ${api}. Available: ${Object.keys(config.endpoints).join(', ')}` } }];
}

return [{
  json: {
    method: endpoint.method,
    url: config.base_url + endpoint.path,
    query: endpoint.query || {},
    body: endpoint.body || {},
    api: api,
    action: action
  }
}];

const input = $input.first().json;
const request = $('Build API Request').first().json;

if (input.error || input.statusCode >= 400) {
  return [{
    json: {
      error: true,
      api: request.api,
      action: request.action,
      status_code: input.statusCode || 500,
      message: input.message || input.error || 'API call failed',
      raw_error: input
    }
  }];
}

return [{
  json: {
    success: true,
    api: request.api,
    action: request.action,
    data: input.data || input.body || input,
    metadata: {
      timestamp: new Date().toISOString(),
      execution_id: $execution.id
    }
  }
}];
